import (
	"net/http"
	"testing"
)

// A member of a list must not crash when the list's owner closes their
// account; the list goes with the owner.
func TestGetListAfterOwnerClosesAccount(t *testing.T) {
	c := newClient(t)
	var list struct{ ID string }
	if code := c.do("tok-bo", http.MethodPost, "/v1/lists", `{"name":"groceries"}`, &list); code != http.StatusCreated {
		t.Fatalf("create list: status %d", code)
	}
	if code := c.do("tok-bo", http.MethodPost, "/v1/lists/"+list.ID+"/members", `{"user":"ana","role":"viewer"}`, nil); code != http.StatusNoContent {
		t.Fatalf("add member: status %d", code)
	}
	if code := c.do("tok-bo", http.MethodDelete, "/v1/me", "", nil); code != http.StatusNoContent {
		t.Fatalf("close account: status %d", code)
	}
	if code := c.do("tok-ana", http.MethodGet, "/v1/lists/"+list.ID, "", nil); code != http.StatusNotFound {
		t.Errorf("get list after owner closed account: status %d, want 404", code)
	}
}
"}

